# Figure 3: one row per selected test mask: real image with simulated needle, mask, and three
# images generated by scripts/04_inference/inference.py.
#
# inference.py names its output folders mask_<idx>, where <idx> is the position of the mask in the
# sorted mask directory, so the real image and mask are looked up by the same sorted index.

import argparse
import os
import matplotlib.pyplot as plt
from PIL import Image

# Test-set mask indices used for Figure 3
DEFAULT_INDICES = [230, 355, 464, 1237, 1674, 1708, 2038, 2092, 2649, 3544, 3707, 4417]


def main():
    parser = argparse.ArgumentParser(description="Real / mask / generated rows for selected masks.")
    parser.add_argument("--inference_dir", default="outputs/inference_results")
    parser.add_argument("--test_dir", default="data/controlnet_dataset/test")
    parser.add_argument("--save_dir", default="outputs/figures/inference_rows")
    parser.add_argument("--indices", type=int, nargs="+", default=DEFAULT_INDICES)
    args = parser.parse_args()

    os.makedirs(args.save_dir, exist_ok=True)

    img_dir = os.path.join(args.test_dir, "images")
    mask_dir = os.path.join(args.test_dir, "conditioning_images")
    frames = sorted(f for f in os.listdir(mask_dir) if f.endswith(".png"))

    titles = ["Real Image", "Mask", "Gen 1", "Gen 2", "Gen 3"]

    for idx in args.indices:
        folder_name = f"mask_{idx:03d}"
        folder_path = os.path.join(args.inference_dir, folder_name)

        images = [
            Image.open(os.path.join(img_dir, frames[idx])),
            Image.open(os.path.join(mask_dir, frames[idx])),
        ] + [Image.open(os.path.join(folder_path, f"gen_{g}.png")) for g in (1, 2, 3)]

        fig, axes = plt.subplots(1, 5, figsize=(15, 3))

        for i in range(5):
            if i <= 1:  # Real Image + Mask
                axes[i].imshow(images[i], cmap='gray')
            else:
                axes[i].imshow(images[i])
            axes[i].set_title(titles[i], fontsize=12)
            axes[i].axis("off")

        plt.tight_layout()

        save_path = os.path.join(args.save_dir, f"{folder_name}.png")
        plt.savefig(save_path, dpi=300)
        plt.close()

        print(f"Saved: {save_path}  ({frames[idx]})")


if __name__ == "__main__":
    main()
